function pickerResults(query=''){let list=pickerKind==='wave'?model.waves.map(w=>({id:w.id,title:text(w.title,w.id),kind:w.isDraft!==false?'Draft plan':'Wave preview'})):pickerKind==='story'?model.nodes.filter(n=>n.kind==='story'&&model.descendants(state.cap).has(n.id)).map(n=>({...n,kind:'User story'})):model.caps.map(c=>({...c,kind:'Capability'}));list=list.filter(n=>(n.id+' '+n.title).toLocaleLowerCase().includes(query.toLocaleLowerCase()));const start=pickerPage*5;$('#picker-results').replaceChildren(...list.slice(start,start+5).map(n=>{const b=button('',()=>{if(pickerKind==='wave')selectWave(n.id);else if(pickerKind==='story'){state.story=n.id;$('#inspector').close();render();}else openCap(n.id);},{class:'board-card'});b.append(el('strong',{text:n.title}),small(n.kind+' · '+n.id));return b;}));if(!list.length)$('#picker-results').append(p('No matches.'));$('#picker-count').textContent=`${list.length} match · showing ${list.length?start+1:0}–${Math.min(start+5,list.length)}`;$('#picker-prev').disabled=pickerPage===0;$('#picker-next').disabled=start+5>=list.length;}
function openPicker(kind){pickerKind=kind;pickerPage=0;show('Find a '+kind,el('label',{for:'picker-search',text:'Search recorded '+kind+' names or IDs'}),el('input',{type:'search',id:'picker-search',oninput:e=>{pickerPage=0;pickerResults(e.target.value);}}),small('At most five results per page.'),p('', 'secondary'),el('div',{id:'picker-results'}),p('','secondary'),el('div',{class:'row'},button('Previous',()=>{pickerPage--;pickerResults($('#picker-search').value);},{id:'picker-prev'}),button('Next',()=>{pickerPage++;pickerResults($('#picker-search').value);},{id:'picker-next'})));const count=el('p',{id:'picker-count',class:'secondary'});$('#picker-results').before(count);pickerResults();$('#picker-search').focus();}
function preview(node,title,description,status,why){const open=()=>{if(matchMedia('(max-width:650px)').matches||$('#inspector').open)return;const box=$('#preview');box.replaceChildren(el('strong',{text:title}),p(description||'Description not tracked yet.'),p(status),p('Why: '+why));box.hidden=false;node.setAttribute('aria-describedby','preview');const r=node.getBoundingClientRect(),h=box.getBoundingClientRect().height;box.style.left=Math.max(12,Math.min(innerWidth-312,r.right+10))+'px';box.style.top=Math.max(12,Math.min(innerHeight-h-12,r.top))+'px';};node.addEventListener('pointerenter',open);node.addEventListener('focus',open);node.addEventListener('pointerleave',()=>$('#preview').hidden=true);node.addEventListener('blur',()=>$('#preview').hidden=true);}
async function readJSON(path){const response=await fetch(path,{method:'GET',cache:'no-store'});if(!response.ok)throw new Error('HTTP '+response.status);const data=await response.json();if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('Malformed status object');return data;}
async function load(reset=false){const token=++generation;if(reset){lastPayload=null;failure='';state.cap=null;state.selected=null;state.story=null;state.wave=null;state.replay=null;}try{let data;if(state.mode==='live')data=await readJSON('/api/status');else if(state.mode==='synthetic')data=await readJSON('/fixtures/synthetic.json');else{data=await readJSON('/fixtures/'+state.project+'.json');if(state.project==='linkshelf'){const planning=await readJSON('/fixtures/linkshelf-planning.json'),meta=arr(planning.meta)[0]||{},approvals=arr(planning.acceptance_approvals);let approval={};if(approvals.length){try{approval=obj(JSON.parse(str(approvals.at(-1).result_json)));}catch{approval={};}}data={...data,plan:{...meta,spine:arr(planning.nodes).map(n=>({...n,parents:sourceJSON(n.parents_json),fields:sourceJSON(n.fields_json)})),},historyApproval:approval,historyPlanning:planning};}}if(token!==generation)return;failure='';lastPayload=data;model=normalize(data);$('#freshness').textContent='Received '+new Date().toLocaleTimeString();render();}catch(error){if(token!==generation)return;failure=error instanceof SyntaxError?'Malformed JSON received':text(error.message,'Source unavailable');model=normalize(lastPayload);$('#freshness').textContent='Refresh unavailable';render();}}
document.querySelectorAll('[data-palette]').forEach(b=>{if(b.tagName==='BUTTON')b.addEventListener('click',()=>{state.palette=b.dataset.palette;render();});});$('#plain').addEventListener('click',()=>{state.plain=!state.plain;render();});document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{state.view=b.dataset.view;render();}));$('#source').addEventListener('change',e=>{const value=e.target.value;state.mode=value==='synthetic'?'synthetic':value==='live'?'live':'history';if(state.mode==='history')state.project=value;load(true);});$('#needs').addEventListener('click',decisions);$('#blocking').addEventListener('click',blockers);$('#where').addEventListener('click',()=>show('Where we are',p($('#where strong').textContent),p(model.currentWave?'Current wave is explicitly recorded. Selecting a lens does not advance it.':'The current stage is not a real execution wave. No first or draft wave is treated as current.'),record(model.where)));document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#preview').hidden=true;});document.addEventListener('scroll',()=>$('#preview').hidden=true,{capture:true,passive:true});load();setInterval(()=>{if(state.mode==='live'&&!document.hidden)load();},5000);
$('#recorded-reviews').addEventListener('click',recordedReviews);
